  31 /**
  32  * Higher-order function to wrap API route handlers with authentication checks.
  33  * @param handler - The API route handler function.
  34  * @param options - Options to specify authentication requirements (e.g., requireAdmin).
  35  * @returns A Next.js API route handler.
  36  */
  37 export const withAuth = (handler: ApiHandler, options: ApiHandlerOptions = {}) => {
  38   return async (request: NextRequest, { params }: { params: Promise<{ [key: string]: string }> }) => {
  39     try {
  40       const authorization = request.headers.get('Authorization');
  41       if (!authorization?.startsWith('Bearer ')) {
  42         return handleApiError({ message: 'Unauthorized: Missing token' }, 401);
  43       }
  44       const token = authorization.substring(7);
  45 
  46       const authRepo = container.resolve<any>(IAuthRepositoryToken);
  47       const authResult = await authRepo.verifyToken(token);
  48 
  49       if (authResult.isFailure) {
  50         return handleApiError({ message: 'Unauthorized: Invalid token' }, 401);
  51       }
  52 
  53       const decodedUser = authResult.getValue();
  54 
  55       const userRepo = container.resolve<any>(IUserRepositoryToken);
  56       const userResult = await userRepo.getById(decodedUser.uid);
  57 
  58       if (userResult.isFailure) {
  59         return handleApiError({ message: 'Forbidden: User profile not found' }, 403);
  60       }
  61 
  62       const user = userResult.getValue();
  63 
  64       if (options.requireAdmin && user.role !== 'admin') {
  65         return handleApiError({ message: 'Forbidden: Admin access required' }, 403);
  66       }
  67 
  68       const awaitedParams = await params;
  69       return handler({ request, user, token, params: awaitedParams });
  70     } catch (error: any) {
  71       // All errors, including auth errors, are now piped through the central handler
  72       return handleApiError(error);
  73     }
  74   };
  75 };
