  92   const firebaseError = handleFirebaseError(error);
  93   if (firebaseError instanceof CustomFirebaseError) {
  94     let status = 400; // Default for many auth errors
  95     if (firebaseError.code.includes('not-found')) status = 404;
  96     if (firebaseError.code.includes('permission-denied')) status = 403;
  97     if (firebaseError.code.includes('already-exists')) status = 409;
  98     if (firebaseError.code.includes('unauthenticated') || firebaseError.code.includes('token-expired')) status = 401;
  99 
 100     return NextResponse.json({ message: firebaseError.message, code: firebaseError.code }, { status });
 101   }
 102 
 103   // 3. Handle custom thrown errors (e.g., from our own logic)
 104   if (error.status && error.message) {
 105     return NextResponse.json({ message: error.message }, { status: error.status });
 106   }
 107 
 108   // 4. Fallback for generic/unexpected errors
 109   const message = error.message || 'An unexpected server error occurred.';
 110   const status = error.status || defaultStatus;
 111 
 112   return NextResponse.json({ message }, { status });
